(* [comment removed for export] *)
Fixpoint qchain_to (m : mem) (bs : list batch) (tl : Z) : Prop :=
  match bs with
  | [] => True
  | (b, ents) :: rest => qbatch m b (match rest with [] => tl | (b', _) :: _ => b' end) ents /\ qchain_to m rest tl
  end.

