(* [comment removed for export] *)
Fixpoint q_dec64 (k : nat) (bs : list byte) : list word :=
  match k with O => [] | S k' => le_bytes_to_word (firstn 8 bs) :: q_dec64 k' (skipn 8 bs) end.

